bool reap_task_mm(struct task_struct *tsk, struct mm_struct *mm) {
    bool success = false;

    task_lock(tsk);
    if (down_read_trylock(&mm->mmap_lock)) {
        if (!atomic_read(&mm->mm_notifier_count) && !test_bit(MMF_OOM_SKIP, &mm->flags)) {
            set_bit(MMF_UNSTABLE, &mm->flags);
            struct vm_area_struct *vma, *vma_next;
            for (vma = mm->mmap; vma; vma = vma_next) {
                vma_next = vma->vm_next;
                if ((vma->vm_flags & (VM_ANON | VM_SHARED)) == VM_ANON) {
                    do_munmap(mm, vma->vm_start, vma->vm_end - vma->vm_start, 0);
                }
            }
            success = true;
        }
        up_read(&mm->mmap_lock);
    }
    task_unlock(tsk);

    return success;
}

bool reap_task_mm(struct task_struct *tsk, struct mm_struct *mm) {
    down_read(&mm->mmap_lock);
    if (atomic_read(&mm->mm_count) < 1) {
        up_read(&mm->mmap_lock);
        return false;
    }

    if (test_bit(MMF_OOM_SKIP, &mm->flags)) {
        up_read(&mm->mmap_lock);
        return false;
    }

    set_bit(MMF_UNSTABLE, &mm->flags);

    struct vm_area_struct *vma, *vma_next;
    for (vma = mm->mmap; vma; vma = vma_next) {
        vma_next = vma->vm_next;
        if (vma->vm_flags & (VM_ANON | VM_SHARED)) {
            do_munmap(mm, vma->vm_start, vma->vm_end - vma->vm_start, 0);
        }
    }

    clear_bit(MMF_OOM_SKIP, &mm->flags);
    up_read(&mm->mmap_lock);

    return true;
}

bool reap_task_mm(struct task_struct *tsk, struct mm_struct *mm) {
    int ret = false;

    task_lock(tsk);
    if (down_read_trylock(&mm->mmap_lock)) {
        if (!atomic_read(&mm->mm_users) || !mm->oom_skip) {
            mm->oom_skip = 1;

            struct vm_area_struct *vma, *tmp;
            for (vma = mm->mmap; vma; vma = tmp) {
                tmp = vma->vm_next;

                if (vma->vm_flags & (VM_ANON | VM_SHARED)) {
                    do_munmap(mm, vma->vm_start, vma->vm_end - vma->vm_start, 0);
                }
            }

            log_oom_reaping_results(tsk, mm);
            ret = true;
        }
        up_read(&mm->mmap_lock);
    }
    task_unlock(tsk);

    return ret;
}

bool reap_task_mm(struct task_struct *tsk, struct mm_struct *mm)
{
    down_read(&mm->mmap_lock);

    if (test_and_set_bit(MMF_OOM_SKIP, &mm->flags)) {
        up_read(&mm->mmap_lock);
        return false;
    }

    if (!atomic_read(&mm->mm_users)) {
        up_read(&mm->mmap_lock);
        return false;
    }

    lock_task_sighand(tsk);
    if (unlikely(!tsk->sighand)) {
        unlock_task_sighand(tsk);
        up_read(&mm->mmap_lock);
        return false;
    }

    mm->oom_reap_in_progress = true;

    do {
        struct vm_area_struct *vma, *tmp;
        for (vma = mm->mmap; vma; vma = tmp) {
            tmp = vma->vm_next;

            if ((vma->vm_flags & (VM_SHARED | VM_ANON)) == VM_ANON) {
                unmap_anon_vma(vma);
            }
        }
    } while (unlikely(mm->oom_reap_in_progress));

    mm->oom_reap_in_progress = false;
    unlock_task_sighand(tsk);

    up_read(&mm->mmap_lock);

    return true;
}
